136:   static approveStage(cr, approverId, approverRole, comments = '') {
137:     if (cr.status !== ChangeStatuses.PENDING_APPROVAL && cr.status !== ChangeStatuses.ESCALATED) {
138:       throw new Error(`ILLEGAL_TRANSITION: Cannot approve change request in status ${cr.status}`);
139:     }
