141:     // Rule BR-001: Self-approval ban
142:     if (cr.requesterId === approverId) {
143:       const err = new Error('SELF_APPROVAL_VIOLATION: Requesters cannot approve their own change requests');
144:       err.code = 'SELF_APPROVAL_VIOLATION';
145:       throw err;
146:     }
147: 
148:     const currentStage = cr.stages[cr.activeStageIndex];
149:     if (!currentStage) {
150:       throw new Error('STAGE_ERROR: No active pending approval stage found');
151:     }
152: 
153:     // Role verification
154:     const roleRank = { [Roles.EMPLOYEE]: 1, [Roles.MANAGER]: 2, [Roles.APPROVER]: 3, [Roles.AUDITOR]: 3, [Roles.ADMIN]: 4 };
155:     const requiredRank = roleRank[currentStage.requiredRole] || 2;
156:     const approverRank = roleRank[approverRole] || 1;
157: 
158:     if (approverRank < requiredRank) {
159:       const err = new Error(`INSUFFICIENT_ROLE: Required ${currentStage.requiredRole}, received ${approverRole}`);
160:       err.code = 'INSUFFICIENT_ROLE_PERMISSIONS';
161:       throw err;
162:     }
163: 
164:     // Record approval signature
165:     currentStage.approvals.push({
166:       approverId,
167:       approverRole,
168:       comments: comments.trim(),
169:       timestamp: new Date().toISOString()
170:     });
171:     currentStage.status = StepStatuses.APPROVED;
172: 
173:     // Check if subsequent stages exist
174:     if (cr.activeStageIndex + 1 < cr.stages.length) {
175:       cr.activeStageIndex += 1;
176:     } else {
177:       cr.status = ChangeStatuses.APPROVED;
178:     }
179: 
180:     cr.updatedAt = new Date().toISOString();
181:     cr.version += 1;
182:     return cr;
183:   }
